public void generateGraph(Graph<V,E> target, Map<String,V> resultMap) {
    // Check if the graph is already complete bipartite
    if (isCompleteBipartite(target)) {
        resultMap.put("isCompleteBipartite", resultMap.getOrDefault("isCompleteBipartite", true));
        return;
    }

    // Get the number of vertices in the graph
    int n = target.getNumVertices();
    if (n <= 0) {
        return;
    }

    // Create two sets to represent the two partitions of the bipartite graph
    Set<V> partition1 = new HashSet<>();
    Set<V> partition2 = new HashSet<>();

    // Distribute vertices into the two partitions
    for (int i = 0; i < n; i++) {
        if (i % 2 == 0) {
            partition1.add(target.getVertices().get(i));
        } else {
            partition2.add(target.getVertices().get(i));
        }
    }

    // Add edges between the two partitions to make the graph complete bipartite
    for (V v1 : partition1) {
        for (V v2 : partition2) {
            target.addEdge(v1, v2);
        }
    }

    // Mark the graph as complete bipartite in the result map
    resultMap.put("isCompleteBipartite", true);
}

private <V, E> boolean isCompleteBipartite(Graph<V, E> graph) {
    // Check if the graph is bipartite
    boolean isBipartite = true;
    Set<V> visited = new HashSet<>();
    Map<V, Integer> color = new HashMap<>();

    for (V v : graph.getVertices()) {
        if (!visited.contains(v)) {
            if (!bfsCheck(graph, v, visited, color)) {
                isBipartite = false;
                break;
            }
        }
    }

    if (!isBipartite) {
        return false;
    }

    // Check if all edges are between the two sets of vertices
    for (V v : graph.getVertices()) {
        for (V neighbor : graph.getAdjacencyList().get(v)) {
            if (color.get(v).equals(color.get(neighbor))) {
                return false;
            }
        }
    }

    return true;
}

private <V, E> boolean bfsCheck(Graph<V, E> graph, V v, Set<V> visited, Map<V, Integer> color) {
    Queue<V> queue = new LinkedList<>();
    queue.add(v);
    visited.add(v);
    color.put(v, 0);

    while (!queue.isEmpty()) {
        V u = queue.poll();

        for (V neighbor : graph.getAdjacencyList().get(u)) {
            if (!visited.contains(neighbor)) {
                queue.add(neighbor);
                visited.add(neighbor);
                color.put(neighbor, 1 - color.get(u));
            } else if (color.get(neighbor).equals(color.get(u))) {
                return false;
            }
        }
    }

    return true;
}

