public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    if (out == null || schema == null || buffer == null) {
        throw new IllegalArgumentException("Null arguments are not allowed");
    }

    byte[] encoded = schema.toByteArray(message);
    int len = encoded.length;
    if (len > buffer.left()) {
        throw new IOException("Buffer is too small");
    }

    buffer.putCoderInt(len);
    buffer.putBytes(encoded);

    return len;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    if (message == null) {
        throw new IllegalArgumentException("message cannot be null");
    }
    if (out == null) {
        throw new IllegalArgumentException(" OutputStream cannot be null");
    }
    if (schema == null) {
        throw new IllegalArgumentException("Schema cannot be null");
    }
    if (buffer == null) {
        throw new IllegalArgumentException("LinkedBuffer cannot be null");
    }

    int length = schema.getByteCount(message);
    if (length > buffer.buffer.length - buffer.offset - 5) {
        buffer = ensureCapacity(buffer, length);
    }

    buffer.buffer[buffer.offset++] = (byte) (length >> 24);
    buffer.buffer[buffer.offset++] = (byte) (length >> 16);
    buffer.buffer[buffer.offset++] = (byte) (length >> 8);
    buffer.buffer[buffer.offset++] = (byte) length;
    schema.writeBytes(message, buffer);

    return buffer.offset;
}

private static LinkedBuffer ensureCapacity(LinkedBuffer buffer, int length) {
    int newCapacity = buffer.buffer.length << 1;
    while (newCapacity < length + buffer.offset) {
        newCapacity <<= 1;
    }
    byte[] newBuffer = new byte[newCapacity];
    System.arraycopy(buffer.buffer, 0, newBuffer, 0, buffer.offset);
    buffer.buffer = newBuffer;
    return buffer;
}

