private static void buildTypeVariableMap(Class<?> clazz, List<TypeVariable<?>> typeVariables, Map<TypeVariable<?>, Type> typeVariableMap) {
    if (clazz == null || typeVariableMap.containsKey(clazz)) {
        return;
    }

    typeVariableMap.put(clazz, clazz);
    Type genericSuperclass = clazz.getGenericSuperclass();
    if (genericSuperclass instanceof ParameterizedType) {
        ParameterizedType parameterizedSuperclass = (ParameterizedType) genericSuperclass;
        Type[] typeArguments = parameterizedSuperclass.getActualTypeArguments();
        TypeVariable<?>[] superTypeVariables = clazz.getSuperclass().getTypeParameters();
        for (int i = 0; i < typeArguments.length; i++) {
            TypeArgument typeArgument = (TypeArgument) typeArguments[i];
            if (typeArgument.getType() instanceof TypeVariable<?>) {
                TypeVariable<?> typeVariable = (TypeVariable<?>) typeArgument.getType();
                typeVariableMap.put(typeVariable, superTypeVariables[i]);
            }
        }
        buildTypeVariableMap clazz.getSuperclass(), typeVariables, typeVariableMap);
    }

    Type[] genericInterfaces = clazz.getGenericInterfaces();
    for (Type genericInterface : genericInterfaces) {
        if (genericInterface instanceof ParameterizedType) {
            ParameterizedType parameterizedInterface = (ParameterizedType) genericInterface;
            Type[] typeArguments = parameterizedInterface.getActualTypeArguments();
            TypeVariable<?>[] interfaceTypeVariables = clazz.getInterfaces()[typeVariables.indexOf(parameterizedInterface.getRawType())].getTypeParameters();
            for (int i = 0; i < typeArguments.length; i++) {
                TypeArgument typeArgument = (TypeArgument) typeArguments[i];
                if (typeArgument.getType() instanceof TypeVariable<?>) {
                    TypeVariable<?> typeVariable = (TypeVariable<?>) typeArgument.getType();
                    typeVariableMap.put(typeVariable, interfaceTypeVariables[i]);
                }
            }
            buildTypeVariableMap clazz.getInterfaces()[typeVariables.indexOf(parameterizedInterface.getRawType())], typeVariables, typeVariableMap);
        }
    }
}

