static long compressTimeBucket(long timeBucket, int dayStep) {
    long date = timeBucket / 100L; // Extract the date part (YYYYMMDD)
    long day = date % 100L; // Extract the day part (DD)
    long millis = timeBucket % 100L; // Extract the millis part (MMSS)

    // Calculate the new day based on the dayStep
    long newDay = day - (day % dayStep);
    if (newDay == 0) {
        newDay = dayStep;
    }

    // Reconstruct the time bucket with the new day
    return (date - day + newDay) * 100L + millis;
}

static long compressTimeBucket(long timeBucket, int dayStep) {
    if (timeBucket < 100000000 || timeBucket >= 1000000000) {
        throw new IllegalArgumentException("Invalid time bucket format");
    }
    if (dayStep <= 0) {
        throw new IllegalArgumentException("Invalid day step");
    }
    long year = timeBucket / 10000;
    long month = (timeBucket / 100) % 100;
    long day = timeBucket % 100;
    long reformedDay = getReformattedDay(day, dayStep);
    return year * 10000 + month * 100 + reformedDay;
}

private static long getReformattedDay(long day, int dayStep) {
    long reformedDay = day;
    while ((reformedDay - dayStep) % 7 != 0) {
        reformedDay--;
    }
    return reformedDay;
}

long reFormatTimeBucket(long timeBucket, int dayStep) {
    String dateStr = String.format("%08d", timeBucket);
    int year = Integer.parseInt(dateStr.substring(0, 4));
    int month = Integer.parseInt(dateStr.substring(4, 6));
    int day = Integer.parseInt(dateStr.substring(6, 8));

    // Find the nearest day that is a multiple of dayStep
    int nearestDay = ((day - 1) / dayStep) * dayStep + 1;

    // Handle the case where the computed day is the same as the current day
    if (nearestDay == day && nearestDay + dayStep <= 31) {
        nearestDay += dayStep;
    }

    return Integer.parseInt(String.format("%04d%02d%02d", year, month, nearestDay));
}

static long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep <= 0) {
        throw new IllegalArgumentException("dayStep must be greater than 0");
    }
    String dateStr = String.format("%08d", timeBucket);
    int year = Integer.parseInt(dateStr.substring(0, 4));
    int month = Integer.parseInt(dateStr.substring(4, 6));
    int day = Integer.parseInt(dateStr.substring(6, 8));

    if (day < 1 || day > 31 || month < 1 || month > 12 || day + dayStep > 31) {
        throw new IllegalArgumentException("Invalid date or dayStep");
    }

    day += dayStep - 1;
    if (day > 31) {
        day -= 31;
        month += 1;
    }
    if (month > 12) {
        month -= 12;
        year += 1;
    }

    return Long.parseLong(String.format("%04d%02d%02d", year, month, day));
}

static long compressTimeBucket(long timeBucket, int dayStep) {
    long year = timeBucket / 10000;
    int month = (int) (timeBucket / 100) % 100;
    int day = (int) timeBucket % 100;

    // Adjust the day based on dayStep
    day = (day - 1 - (day - 1) % dayStep) + 1;

    return year * 10000 + month * 100 + day;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    int size = 0;
    int endIndex = Math.min(index + len, str.length());
    for (int i = index; i < endIndex; i++) {
        char c = str.charAt(i);
        if ((c & 0x80) == 0) {
            size += 1; // 1 byte for ASCII characters
        } else if ((c & 0xE0) == 0xC0) {
            size += 2; // 2 bytes for UTF-8 characters in the range of 128-2047
        } else if ((c & 0xF0) == 0xE0) {
            size += 3; // 3 bytes for UTF-8 characters in the range of 2048-65535
        } else if ((c & 0xF8) == 0xF0) {
            size += 4; // 4 bytes for UTF-8 characters in the range of 65536-1114111
        }
    }
    return size;
}

