private StackMapTable.VerificationTypeInfo convertToVerificationTypeInfo(Object type) {
    if (type instanceof Integer) {
        return new StackMapTable.VerificationTypeInfo(((Integer) type).byteValue());
    } else if (type instanceof Class<?>) {
        return new StackMapTable.VerificationTypeInfo((Class<?>) type);
    } else if (type instanceof Long) {
        return new StackMapTable.VerificationTypeInfo(((Long) type).longValue());
    } else if (type instanceof Double) {
        return new StackMapTable.VerificationTypeInfo(((Double) type).doubleValue());
    } else {
        throw new IllegalArgumentException("Unsupported type: " + type.getClass());
    }
}

private void putAbstractTypes(final int start, final int end) {
    for (int i = start; i < end; i++) {
        final StackMapFrame.AbstractType abstractType = currentFrame.getAbstractType(i);
        switch (abstractType.getTypeTag()) {
            case ITEM_Top:
                stackMapTableEntries.add(new StackMapTable.VerificationTypeInfo(AbstractTypeVerificationType.TOP));
                break;
            case ITEM_Integer:
                stackMapTableEntries.add(new StackMapTable.VerificationTypeInfo(AbstractTypeVerificationType.INTEGER));
                break;
            case ITEM_Float:
                stackMapTableEntries.add(new StackMapTable.VerificationTypeInfo(AbstractTypeVerificationType.FLOAT));
                break;
            case ITEM_Long:
                stackMapTableEntries.add(new StackMapTable.VerificationTypeInfo(AbstractTypeVerificationType.LONG));
                break;
            case ITEM_Double:
                stackMapTableEntries.add(new StackMapTable.VerificationTypeInfo(AbstractTypeVerificationType.DOUBLE));
                break;
            case ITEM_Class:
                stackMapTableEntries.add(new StackMapTable.VerificationTypeInfo(AbstractTypeVerificationType.CLASS, abstractType.getTypeData()));
                break;
            case ITEM_Array:
                stackMapTableEntries.add(new StackMapTable.VerificationTypeInfo(AbstractTypeVerificationType.ARRAY, abstractType.getTypeData()));
                break;
            case ITEM_Object:
                stackMapTableEntries.add(new StackMapTable.VerificationTypeInfo(AbstractTypeVerificationType.OBJECT, abstractType.getTypeData()));
                break;
            case ITEM_Uninitialized:
                stackMapTableEntries.add(new StackMapTable.VerificationTypeInfo(AbstractTypeVerificationType.UNINITIALIZED, abstractType.getTypeData()));
                break;
            case ITEM_UninitializedThis:
                stackMapTableEntries.add(new StackMapTable.VerificationTypeInfo(AbstractTypeVerificationType.UNINITIALIZED_THIS));
                break;
            default:
                throw new IllegalArgumentException("Invalid type tag: " + abstractType.getTypeTag());
        }
    }
}

