protected <V, E> GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Input cannot be null");
    }

    if (tour.isEmpty()) {
        return null;
    }

    List<E> edgeList = new ArrayList<>(tour);
    V currentVertex = edgeList.get(0).getV();
    List<V> pathVertices = new ArrayList<>();
    pathVertices.add(currentVertex);

    for (E edge : edgeList) {
        if (edge.getV().equals(currentVertex)) {
            currentVertex = edge.getU();
        } else {
            currentVertex = edge.getV();
        }
        pathVertices.add(currentVertex);
    }

    return new SimpleGraphPath<>(graph, pathVertices, edgeList);
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    List<E> edgeList = new ArrayList<>(tour);
    edgeList.sort(Comparator.comparingLong(e -> graph.getEdgeSource(e).hashCode() * 1000000000L + graph.getEdgeTarget(e).hashCode()));

    V startVertex = null;
    for(V vertex : graph.vertexSet()) {
        if(tour.stream().anyMatch(e -> graph.getEdgeSource(e).equals(vertex))) {
            startVertex = vertex;
            break;
        }
    }

    if(startVertex == null) {
        throw new IllegalArgumentException("The provided tour does not contain an edge with a vertex in the graph");
    }

    List<V> vertexList = new ArrayList<>();
    V currentVertex = startVertex;
    vertexList.add(currentVertex);

    while(!tour.isEmpty()) {
        currentVertex = findNextVertex(tour, graph, currentVertex);
        if(currentVertex == null) {
            break;
        }
        vertexList.add(currentVertex);
        tour.remove(graph.getEdge(currentVertex, vertexList.get(vertexList.size() - 2)));
    }

    if(!tour.isEmpty()) {
        throw new IllegalArgumentException("The provided tour contains a ring that cannot be closed");
    }

    return graph.getPath(vertexList);
}

private <V,E> V findNextVertex(Set<E> tour, Graph<V,E> graph, V currentVertex) {
    for(E edge : tour) {
        if(graph.getEdgeSource(edge).equals(currentVertex)) {
            return graph.getEdgeTarget(edge);
        }
    }
    return null;
}

protected GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    if (tour == null || tour.isEmpty() || graph == null) {
        throw new IllegalArgumentException("Input tour or graph cannot be null or empty");
    }

    List<E> edgeList = new ArrayList<>(tour);
    if (edgeList.size() == 1) {
        throw new IllegalArgumentException("Tour must contain at least two edges to form a path");
    }

    GraphPath<V, E> path = new DefaultGraphPath<>();
    Iterator<E> iterator = edgeList.iterator();
    E edge = iterator.next();
    V startVertex = edge.getSource();
    path.endVertex(startVertex);

    while (iterator.hasNext()) {
        V currentVertex = startVertex;
        edge = iterator.next();
        if (edge.getSource().equals(currentVertex)) {
            path.addTarget(edge.getSource(), edge.getTarget());
            path.addEdge(edge);
            startVertex = edge.getTarget();
        } else if (edge.getTarget().equals(currentVertex)) {
            path.addTarget(edge.getTarget(), edge.getSource());
            path.addEdge(edge);
            startVertex = edge.getSource();
        } else {
            throw new IllegalArgumentException("Edges in tour must form a single connected path");
        }
    }

    path.addTarget(startVertex, edge.getSource());
    path.addEdge(edge);
    path.endVertex(edge.getTarget());
    return path;
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    List<E> edges = new ArrayList<>(tour);
    if (edges.isEmpty()) {
        return new GraphPathImpl<>(graph, null, 0.0);
    }

    V startNode = edges.get(0).getHead();
    Iterator<E> iterator = edges.iterator();
    E edge = iterator.next();
    GraphPath.Builder<V,E> pathBuilder = new GraphPathImpl.Builder<>(graph).addEdge(edge);
    double totalWeight = edge.getWeight();

    while (iterator.hasNext()) {
        edge = iterator.next();
        pathBuilder.addVertex(edge.getTarget());
        pathBuilder.addEdge(edge);
        totalWeight += edge.getWeight();
    }

    pathBuilder.addVertex(startNode);
    pathBuilder.setWeight(totalWeight);

    return pathBuilder.build();
}

protected GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    if (tour == null || tour.isEmpty() || graph == null) {
        throw new IllegalArgumentException("Input parameters cannot be null or empty.");
    }

    List<E> edges = new ArrayList<>(tour);
    if (edges.size() == 1) {
        return graph.createPath(edges.get(0));
    }

    V startVertex = null;
    for (E edge : edges) {
        startVertex = graph.getEdgeSource(edge);
        if (graph.degreeOf(startVertex) == 1) {
            break;
        }
    }

    if (startVertex == null) {
        throw new IllegalArgumentException("Tour set does not form a valid path.");
    }

    Iterator<V> vertexIterator = graph.vertexSet().iterator();
    V currentVertex = startVertex;
    List<V> vertexList = new ArrayList<>();
    Set<E> usedEdges = new HashSet<>();

    while (vertexIterator.hasNext()) {
        V nextVertex = vertexIterator.next();
        if (graph.containsEdge(currentVertex, nextVertex) && !usedEdges.contains(graph.getEdge(currentVertex, nextVertex))) {
            vertexList.add(currentVertex);
            usedEdges.add(graph.getEdge(currentVertex, nextVertex));
            currentVertex = nextVertex;
        }
    }

    if (currentVertex != startVertex) {
        throw new IllegalArgumentException("Tour set does not form a valid path.");
    }

    vertexList.add(currentVertex);
    return graph.createPath(vertexList.toArray(new V[0]), edges.toArray(new E[0]));
}

