    for (Map.Entry<Integer, Symbol> entry : constantPool.entrySet()) {
        if (entry.getValue().name.equals(name) && entry.getValue().descriptor.equals(descriptor)) {
            return entry.getKey();
        }
    }
    Symbol newSymbol = new Symbol(name, descriptor, hash);
    constantPool.put(hash, newSymbol);
    return hash;
}

