private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    if (bounds == null) {
        throw new IllegalArgumentException("Bounds list cannot be null");
    }

    int n = bounds.size();
    List<Integer> suffixSum = new ArrayList<>(n);
    long totalSum = 0;

    for (int i = n - 1; i >= 0; i--) {
        if (bounds.get(i) < 0) {
            throw new IllegalArgumentException("Bounds list cannot contain negative numbers");
        }
        totalSum += bounds.get(i);
        if (i < n - 1) {
            suffixSum.add(suffixSum.get(suffixSum.size() - 1));
        } else {
            suffixSum.add(0);
        }
    }

    Collections.reverse(suffixSum);
    suffixSum.add(totalSum);

    return new Pair<>(suffixSum, totalSum);
}

