public class CharUtils {
    private static final ConcurrentHashMap<Character, Character> cache = new ConcurrentHashMap<>();

    public static Character toCharacterObject(final char ch) {
        Character result = cache.get(ch);
        if (result == null) {
            result = new Character(ch);
            cache.put(ch, result);
        }
        return result;
    }
}

