public static String applyRelativePath(String path, String relativePath) {
    // Check for null or empty input strings
    if (path == null || relativePath == null || path.isEmpty() || relativePath.isEmpty()) {
        throw new IllegalArgumentException("Path and relativePath must not be null or empty");
    }

    // Normalize the path and relativePath to use forward slashes and remove any trailing slashes
    String canonPath = path.replace("\\", "/").replaceAll("/+$", "");
    String canonRelativePath = relativePath.replace("\\", "/").replaceAll("/+$", "");

    // Apply the relative path
    if (canonRelativePath.startsWith("..")) {
        int lastSlashIndex = canonPath.lastIndexOf("/");
        if (lastSlashIndex != -1) {
            canonPath = canonPath.substring(0, lastSlashIndex);
        }
        canonicalPath = canonPath + "/" + canonRelativePath.substring(2);
    } else {
        canonPath = canonPath + "/" + canonRelativePath;
    }

    // Return the resulting full file path
    return canonPath;
}

public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Path and relativePath cannot be null");
    }

    // Replace backslashes with slashes
    path = path.replace("\\", "/");
    relativePath = relativePath.replace("\\", "/");

    // Remove any trailing slash from the path
    if (path.endsWith("/")) {
        path = path.substring(0, path.length() - 1);
    }

    // Combine the path and relative path
    String fullPath = path + "/" + relativePath;

    // Replace multiple slashes with a single slash
    fullPath = fullPath.replaceAll("/+", "/");

    return fullPath;
}

